"""Render the three separate prototype compositions from a fixed source snapshot.
No production files are written. Python standard library only.
"""
from pathlib import Path
import json, html
ROOT=Path(__file__).resolve().parent
D=json.loads((ROOT/'content.json').read_text()); A=D['articles']; P=D['paragraphs']
esc=html.escape
S=D['standings']; DS=S['driverStandings']['MRData']['StandingsTable']['StandingsLists'][0]['DriverStandings']; CS=S['constructorStandings']['MRData']['StandingsTable']['StandingsLists'][0]['ConstructorStandings']
NAMES={'a':'Grand Prix Journal','b':'Paddock','c':'Race Notebook'}
def img(src,alt='',cls='',lazy=True):
    return f'<img src="{src}" alt="{esc(alt)}" class="{cls}" loading="{"lazy" if lazy else "eager"}" decoding="async">'
def pic(i,cls='',lazy=True):return img(A[i]['image'],A[i]['title'],cls,lazy)
def href(i):return 'article.html' if i==0 else A[i]['url']
def meta(i):return f'<span class="category">{A[i]["category"]}</span><span>{A[i]["author"]} · <time datetime="{A[i]["date"]}">{A[i]["date"][8:10]}.{A[i]["date"][5:7]}.2026</time></span>'
def story(i,photo=True,excerpt=False):
    return f'<article class="story">{f"<a class=story-image href={href(i)}>{pic(i)}</a>" if photo else ""}<div class="story-copy"><div class="metadata">{meta(i)}</div><h3><a href="{href(i)}">{A[i]["title"]}</a></h3>{f"<p>{A[i][chr(101)+chr(120)+chr(99)+chr(101)+chr(114)+chr(112)+chr(116)]}</p>" if excerpt else ""}<a class="read-link" href="{href(i)}">Διάβασε το άρθρο <span aria-hidden="true">↗</span></a></div></article>'
def brand():return '<a class="brand" href="index.html" aria-label="F1Stories — Αρχική">'+img('/source/images/logo-nav.webp','','brand-mark',False)+'<span>F1<span class="brand-stories">Stories</span><b>.</b></span></a>'
def nav(page):
    return ''.join(f'<a href="{url}"'+(' aria-current="page"' if key==page else '')+f'>{label}</a>' for key,label,url in [('home','Αρχική','index.html'),('article','Journal','index.html#journal'),('media','BetCast','index.html#media'),('data','Data Hub','data.html'),('people','Η παρέα','index.html#people')])
def header(c,page):
    links=nav(page)
    menu='<button class="menu-toggle" aria-expanded="false" aria-controls="main-nav">Μενού <span aria-hidden="true">☰</span></button>'
    if c=='a':return f'<header class="masthead"><div class="masthead-top"><span>Η ελληνική F1 κοινότητα</span><a href="index.html#radio">Team Radio ↗</a></div><div class="masthead-brand">{brand()}<p>Ιστορίες που μένουν. Αγώνες που μας ενώνουν.</p>{menu}</div><nav id="main-nav" aria-label="Κύρια πλοήγηση">{links}</nav></header>'
    if c=='b':return f'<header class="station-header">{brand()}<span class="station-tag">Η F1 έχει παρέα.</span>{menu}<nav id="main-nav" aria-label="Κύρια πλοήγηση">{links}<a class="radio-nav" href="index.html#radio">Team Radio ↗</a></nav></header>'
    return f'<header class="notebook-header">{brand()}<span class="notebook-caption">Τεχνική ματιά.<br>Καθαρή άποψη.</span>{menu}<nav id="main-nav" aria-label="Κύρια πλοήγηση">{links}<a href="index.html#radio">Team Radio ↗</a></nav><div class="spine-note">Formula 1<br>Ανάλυση · Ιστορία<br>Ελληνική κοινότητα</div><a class="review-return" href="/">← Design review</a></header>'
def foot(c):
    return '<footer class="footer"><div><a class="footer-brand" href="index.html">F1Stories.</a><p>Τεχνική ανάλυση, άποψη και ελληνική F1 κοινότητα.</p></div><div class="footer-links"><a href="https://www.youtube.com/@f1_stories_original">YouTube ↗</a><a href="https://www.instagram.com/myf1stories/">Instagram ↗</a><a href="mailto:myf1stories@gmail.com">Επικοινωνία ↗</a></div><div class="footer-bottom"><span>© 2026 F1 Stories</span><a href="https://f1stories.gr/privacy/privacy.html">Πολιτική απορρήτου</a><a href="https://f1stories.gr/privacy/terms.html">Όροι χρήσης</a><a href="/">Design review · '+c.upper()+'</a></div></footer>'
def sponsors():
    entries=[('Balatzis','Μπαλατζής Χωματουργικά','https://georgiosbalatzis.github.io/excavatorsPage/'),('ps','Πουρτσίδης Γεννήτριες','https://pourtsidisgenerators.gr/'),('BalatzisDomika','Μπαλατζής Δομικά','https://georgiosbalatzis.github.io/excavatorsPage/#domika'),('am','Αμβροσιάδης','https://ambrosiadis.gr/'),('bedhome','Bed and Home','https://www.bedandhome.gr/'),('GrandRealm','Grand Realm','https://www.grandrealm.gr/')]
    return '<section class="partners" aria-label="Οι συνεργάτες μας"><p class="eyebrow">Μαζί στην εκκίνηση · Οι συνεργάτες μας</p><div>'+''.join(f'<a href="{u}" rel="sponsored">{img("/source/images/sponsors/normalized/"+f+".webp",n)}</a>' for f,n,u in entries)+'</div></section>'
def people():
    return '<section id="people" class="people"><div class="section-heading"><div><span class="eyebrow">Οι άνθρωποι του F1Stories</span><h2>Η δική μας παρέα.</h2></div><a href="https://f1stories.gr/authors/">Όλη η ομάδα ↗</a></div><div class="cast">'+''.join(f'<a href="https://f1stories.gr/authors/?author={slug}">{img("/source/images/authors/"+im+".webp",n)}<div><h3>{n}</h3><p>{role}</p></div></a>' for im,n,role,slug in [('giannis','Γιάννης Πουλικίδης','Παρουσιαστής · Στοιχηματική ανάλυση','giannis-poulikidis'),('georgios','Γιώργος Μπαλατζής','Παρουσιαστής · Τεχνικός αναλυτής','georgios-balatzis'),('dimitris','Δημήτρης Κεραμιδιώτης','Παρουσιαστής','dimitris-keramidiotis'),('thanasis','Θανάσης Μπαταλάς','Παρουσιαστής · Ιστορική αναδρομή','thanasis-batalas')])+'</div></section>'
def radio():return '<section class="radio" id="radio"><span class="eyebrow">Το δικό σου Team Radio</span><h2>Έχεις κάτι να πεις;</h2><p>Μια ιδέα, μια διαφωνία, μια συνεργασία.<br>Η κουβέντα ξεκινάει από εδώ.</p><a href="mailto:myf1stories@gmail.com">myf1stories@gmail.com ↗</a></section>'
def player():return '<div class="player"><button class="play-button" data-video="l0vNNK6FO3g" aria-label="Φόρτωση BetCast 270 από το YouTube">'+img('/assets/betcast-270.jpg','BetCast #270 Hungaroring — εικόνα επεισοδίου','',False)+'<span class="play-icon" aria-hidden="true">▶</span><span class="play-caption">Προβολή επεισοδίου</span></button></div>'
def media(c):
    return f'<section class="media media-{c}" id="media"><div class="media-heading"><span class="eyebrow">F1Stories στο YouTube</span><h2>{"Στην ίδια συχνότητα." if c=="a" else "Η κουβέντα συνεχίζεται." if c=="b" else "Από το μικρόφωνο."}</h2></div>{player()}<div class="episode"><span class="eyebrow">BetCast · 25 Ιουλίου 2026</span><h3>BetCast #270<br>Hungaroring</h3><p>Γιάννης Πουλικίδης<br>Γιώργος Μπαλατζής</p><p>Αγωνιστική πρόβλεψη, ρυθμός και επιλογές πριν από το Grand Prix.</p><a href="{D["video"]["url"]}">Άνοιξε στο YouTube ↗</a></div></section>'
def smallscores(n=3):return '<ol class="small-scores">'+''.join(f'<li><span class="position">{d["position"]}</span><span>{d["Driver"]["givenName"]} {d["Driver"]["familyName"]}<small>{d["Constructors"][0]["name"]}</small></span><strong>{d["points"]}<small>βαθμοί</small></strong></li>' for d in DS[:n])+'</ol>'
def datasummary(c):return f'<section class="data-summary"><div><span class="eyebrow">F1 Data Hub · 2026</span><h2>{"Κάθε βαθμός,<br>μια ιστορία." if c=="a" else "Το grid σε αριθμούς." if c=="b" else "Η εικόνα του πρωταθλήματος."}</h2><p>Οδηγοί, ομάδες και οι λεπτομέρειες που κρίνουν τον αγώνα.</p><a class="read-link" href="data.html">Δες τη βαθμολογία ↗</a></div><div>{smallscores()}<p class="source-note">Στιγμιότυπο 22.08.2026 · Μετά τον γύρο 11</p></div></section>'
def home_a():
    return f'<section class="cover"><div class="cover-label"><span>Η ιστορία του εξωφύλλου</span><span>History · 14 Σεπτεμβρίου 2026</span></div><a class="cover-photo" href="article.html">{pic(0,lazy=False)}</a><div class="cover-title"><span class="eyebrow">Mika Salo</span><h1><a href="article.html">Ο οδηγός που<br>πάντα πρόσφερε.</a></h1></div><div class="cover-deck"><p>{P[0]}</p><div class="metadata">Themis Charvalis · 3′ ανάγνωση</div><a class="read-link" href="article.html">Διάβασε την ιστορία ↗</a></div></section><section id="journal" class="journal"><div class="section-heading"><h2>Το Journal.</h2><a href="https://f1stories.gr/blog-module/blog/index.html">Όλες οι ιστορίες ↗</a></div><div class="journal-spread">{story(1,True,True)}<div class="journal-index">{story(3,False)}{story(2,False)}{story(4,False)}</div></div><div class="technical-feature">{story(5,True,True)}</div></section>{media("a")}{datasummary("a")}{people()}{radio()}{sponsors()}'
def home_b():
    return f'<div class="edition-line"><span>F1Stories · Ιστορίες, ανάλυση, παρέα</span><a href="#media">Στο μικρόφωνο: BetCast ↗</a></div><section class="broadcast-stage"><div class="headline-stage"><div class="metadata">{meta(0)}</div><h1><a href="article.html">{A[0]["title"]}</a></h1><a class="lead-photo" href="article.html">{pic(0,lazy=False)}<span>Διάβασε την ιστορία ↗</span></a></div><aside class="programme" id="media"><span class="programme-label">ΣΤΟ ΜΙΚΡΟΦΩΝΟ</span>{player()}<span class="eyebrow">25 Ιουλίου 2026 · YouTube</span><h2>BetCast #270<br>Hungaroring</h2><p>Αγωνιστική πρόβλεψη, ρυθμός και επιλογές πριν από το Grand Prix.</p><div class="programme-presenters">{img("/source/images/authors/giannis.webp","Γιάννης Πουλικίδης",lazy=False)}{img("/source/images/authors/georgios.webp","Γιώργος Μπαλατζής",lazy=False)}<p>Γιάννης Πουλικίδης<br>Γιώργος Μπαλατζής</p></div><a href="{D["video"]["url"]}">Δες το επεισόδιο ↗</a></aside></section><section id="journal" class="journal"><div class="section-heading"><h2>Στο επίκεντρο.</h2><a href="https://f1stories.gr/blog-module/blog/index.html">Το Journal ↗</a></div><div class="newsline">{story(1)}{story(3)}{story(2)}</div><div class="analysis-pair">{story(4,True,True)}{story(5,True,True)}</div></section>{people()}{datasummary("b")}{radio()}{sponsors()}'
def home_c():
    return f'<div class="notebook-topline"><span>F1Stories / Το σημειωματάριο</span><span>Ιστορία · Άποψη · Δεδομένα</span></div><section class="notebook-intro"><div><span class="eyebrow">Η Formula 1, από τη δική μας οπτική.</span><h1>Πίσω από τον αγώνα,<br>υπάρχει μια ιστορία.</h1></div><p>Τεχνική ανάλυση, άποψη και ελληνική F1 κοινότητα.</p></section><section class="notebook-feature"><div class="feature-record"><div class="metadata">{meta(0)}</div><h2><a href="article.html">{A[0]["title"]}</a></h2><div class="feature-body"><a href="article.html">{pic(0,lazy=False)}</a><div><p>{P[0]}</p><a class="read-link" href="article.html">Άνοιξε την ιστορία ↗</a><span class="reading-note">3 λεπτά ανάγνωσης</span></div></div></div><aside class="reference"><span class="eyebrow">Αναφορά πρωταθλήματος</span><h2>2026 <small>/ Γύρος 11</small></h2>{smallscores()}<p class="source-note">Στιγμιότυπο 22.08.2026<br>Πηγή: Jolpica F1</p><a href="data.html">Πλήρης βαθμολογία ↗</a></aside></section><section class="journal" id="journal"><div class="section-heading"><h2>Πρόσφατες καταγραφές</h2><a href="https://f1stories.gr/blog-module/blog/index.html">Όλο το Journal ↗</a></div><div class="record-index">{story(1)}{story(3)}{story(2)}{story(4)}</div><div class="technical-feature"><span class="eyebrow">Τεχνικό δελτίο</span>{story(5,True,True)}</div></section>{media("c")}{people()}{radio()}{sponsors()}'
def authorcredit():return '<a class="author-credit" href="https://f1stories.gr/authors/?author=themis-charvalis">'+img('/source/images/avatars/AS.webp','','',False)+'<span>Γράφει ο <strong>Themis Charvalis</strong><small>14 Σεπτεμβρίου 2026 · 3 λεπτά ανάγνωσης</small></span></a>'
def articlebody():
    body=''
    for i,p in enumerate(P):
        if i==3:body+='<h2 id="ferrari">Μέρος μιας ομάδας</h2>'
        if i==8:body+='<aside class="pull-text"><p>«Δεν θυμόμαστε μόνο τα αποτελέσματα. Θυμόμαστε τον πιλότο.»</p><span>Από το κείμενο του Themis Charvalis</span></aside><h2 id="legacy">Οι άνθρωποι και οι ιστορίες τους</h2>'
        body+=f'<p{ " class=opening" if i==0 else ""}>{p}</p>'
    return body

def gallery():return '<section class="article-gallery" id="gallery" aria-label="Φωτογραφίες άρθρου"><figure>'+img('/source/blog-module/blog-entries/20260914W/3.webp','Φωτογραφία από το άρθρο για τον Mika Salo')+'<figcaption>Mika Salo · Από τη συλλογή εικόνων του άρθρου.</figcaption></figure><figure>'+img('/source/blog-module/blog-entries/20260914W/4.webp','Δεύτερη φωτογραφία από το άρθρο για τον Mika Salo')+'<figcaption>Από το φωτογραφικό αρχείο της ιστορίας.</figcaption></figure></section>'
def articleindex():return '<details class="reading-index" open><summary>Στην ιστορία</summary><a href="#reading">Η διαδρομή</a><a href="#ferrari">Μέρος μιας ομάδας</a><a href="#legacy">Οι ιστορίες που μένουν</a><a href="#gallery">Φωτογραφικό αρχείο</a></details>'
def article(c):
    title=f'<span class="eyebrow">Journal · History</span><h1>{A[0]["title"]}</h1>{authorcredit()}'
    hero='<figure class="article-hero">'+img('/source/blog-module/blog-entries/20260914W/2.webp','Το κόκκινο μονοθέσιο Ferrari από το άρθρο για τον Mika Salo','',False)+'<figcaption>Η Ferrari της ιστορίας του Mika Salo · Εικόνα από το αρχικό άρθρο.</figcaption></figure>'
    provenance='<details class="provenance"><summary>Συντακτική ταυτότητα & πηγή</summary><p>Το πλήρες κείμενο του Themis Charvalis, όπως δημοσιεύτηκε στο F1Stories στις 14 Σεπτεμβρίου 2026. Οι ενδιάμεσοι τίτλοι και οι περιγραφικές λεζάντες προστέθηκαν για αυτή τη μελέτη σχεδιασμού.</p><a href="'+A[0]['url']+'">Πρωτότυπη δημοσίευση ↗</a></details>'
    body=f'<div class="prose" id="reading">{articlebody()}{provenance}</div>'
    related=f'<section class="related"><div class="section-heading"><h2>Η επόμενη ιστορία.</h2><a href="index.html#journal">Πίσω στο Journal ↗</a></div><div>{story(3)}{story(2)}</div></section>'
    if c=='a':return f'<article class="reading-article"><header class="article-heading">{title}</header>{hero}<div class="reading-layout"><aside class="article-margin"><span class="eyebrow">Η ιστορία πίσω<br>από το κράνος.</span>{articleindex()}</aside>{body}</div>{gallery()}<div class="author-end">{authorcredit()}<p>Αναζητά το ανθρώπινο κομμάτι πίσω από τα αποτελέσματα και γράφει ιστορίες που συνδέουν το τότε με το σημερινό grid.</p></div></article>{related}'
    if c=='b':return f'<article class="reading-article"><header class="article-heading">{title}</header>{hero}<div class="reading-layout">{body}<aside class="article-margin"><span class="eyebrow">Η φωνή της ιστορίας</span>{authorcredit()}<p>Αναζητά το ανθρώπινο κομμάτι πίσω από τα αποτελέσματα.</p>{articleindex()}<a class="read-link" href="index.html#media">Μετά την ανάγνωση: BetCast ↗</a></aside></div>{gallery()}</article>{related}'
    return f'<article class="reading-article"><div class="notebook-topline"><a href="index.html#journal">← Το Journal</a><span>Ιστορία οδηγού · Mika Salo</span></div><header class="article-heading">{title}</header><div class="document-layout"><aside class="article-margin">{articleindex()}<dl><dt>Κατηγορία</dt><dd>History</dd><dt>Δημοσίευση</dt><dd>14.09.2026</dd><dt>Χρόνος ανάγνωσης</dt><dd>3 λεπτά</dd></dl></aside><div>{hero}{body}</div></div>{gallery()}</article>{related}'
def table(kind):
    rows=DS if kind=='drivers' else CS
    s=f'<table><caption>Βαθμολογία {"οδηγών" if kind=="drivers" else "κατασκευαστών"} · 2026 · Γύρος 11</caption><thead><tr><th scope="col">Θέση</th><th scope="col">{"Οδηγός / Ομάδα" if kind=="drivers" else "Κατασκευαστής"}</th><th scope="col">Νίκες</th><th scope="col">Βαθμοί</th></tr></thead><tbody>'
    for d in rows:
        driver=kind=='drivers'; name=(d['Driver']['givenName']+' '+d['Driver']['familyName']) if driver else d['Constructor']['name']; team=d['Constructors'][0]['name'] if driver else d['Constructor']['nationality']; icon='/source/images/'+('drivers/'+{'max_verstappen':'verstappen','arvid_lindblad':'lindblad'}.get(d['Driver']['driverId'],d['Driver']['driverId']) if driver else 'teams/'+d['Constructor']['constructorId'])+'.webp'
        s+=f'<tr><td class="rank">{d["position"]}</td><th scope="row"><div class="competitor">{img(icon,"",lazy=False)}<span>{name}<small>{team}</small></span></div></th><td class="numeric">{d["wins"]}</td><td class="points numeric">{d["points"]}</td></tr>'
    return s+'</tbody></table>'
def chart(kind):
    rows=DS[:10] if kind=='drivers' else CS;maximum=float(rows[0]['points'])
    return '<div class="points-chart"><h3>Κατανομή βαθμών'+(' · Top 10' if kind=='drivers' else '')+'</h3>'+''.join(f'<div class="bar-row"><span>{d["Driver"]["familyName"] if kind=="drivers" else d["Constructor"]["name"]}</span><div class="bar-track"><div class="bar" style="width:{float(d["points"])/maximum*100:.3f}%"></div></div><strong>{d["points"]}</strong></div>' for d in rows)+'</div>'
def reportnav():return '<div class="report-switch" role="group" aria-label="Επιλογή βαθμολογίας"><button aria-pressed="true" data-report="drivers" aria-controls="report-drivers">Οδηγοί</button><button aria-pressed="false" data-report="constructors" aria-controls="report-constructors">Κατασκευαστές</button></div>'
def reports():
    return ''.join(f'<section id="report-{k}" class="report-panel" aria-label="Βαθμολογία {"οδηγών" if k=="drivers" else "κατασκευαστών"}" {"hidden" if k=="constructors" else ""}><div class="table-wrap">{table(k)}</div>{chart(k)}</section>' for k in ['drivers','constructors'])
def data(c):
    title='<span class="eyebrow">F1 Data Hub</span><h1>Κάθε βαθμός,<br>μια ιστορία.</h1><p>Βαθμολογίες Πρωταθλήματος</p>'
    source='<div class="snapshot-label"><span>Σεζόν 2026 · Μετά τον γύρο 11</span><span>Στιγμιότυπο 22 Αυγούστου 2026</span></div>'
    explanation='<aside class="data-explanation"><span class="eyebrow">Διαβάζοντας τη βαθμολογία</span><h2>Η εικόνα πίσω από τους αριθμούς.</h2><p>Οδηγοί, ομάδες και οι λεπτομέρειες που κρίνουν τον αγώνα. Διάβασε τη σεζόν μέσα από τα δεδομένα.</p><p>Οι βαθμοί και οι νίκες παρουσιάζονται όπως καταγράφονται στο αποθηκευμένο στιγμιότυπο του F1Stories μετά τον γύρο 11. Οι ισοβαθμίες διατηρούν τη σειρά της πηγής.</p><dl><dt>Πηγή</dt><dd><a href="https://github.com/jolpica/jolpica-f1">Jolpica F1 ↗</a></dd><dt>Τελευταία ενημέρωση στιγμιοτύπου</dt><dd>22 Αυγούστου 2026</dd></dl><p class="source-note">Αρχειακό στιγμιότυπο για τη μελέτη σχεδιασμού. Δεν αποτελεί ζωντανή ενημέρωση.</p><a class="read-link" href="https://f1stories.gr/standings/">Τρέχον F1 Data Hub ↗</a><div class="more-reports"><h3>Πέρα από τους βαθμούς</h3><a href="https://f1stories.gr/standings/?tab=quali-gaps">Quali Gaps ↗</a><a href="https://f1stories.gr/standings/?tab=tyre-pace">Tyre Pace ↗</a><a href="https://f1stories.gr/standings/?tab=pit-stops">Pit Stops ↗</a><a href="https://f1stories.gr/standings/?tab=debrief">Debrief ↗</a></div></aside>'
    lead=f'<div class="leader-summary"><div><span class="eyebrow">Πρωτοπόρος οδηγών</span><h2>Andrea Kimi<br>Antonelli</h2><span>Mercedes</span></div>{img("/source/images/drivers/antonelli.webp","Andrea Kimi Antonelli",lazy=False)}<div class="leader-numbers"><strong>{DS[0]["points"]}<small>βαθμοί</small></strong><strong>{DS[0]["wins"]}<small>νίκες</small></strong></div></div>'
    if c=='a':return f'<header class="data-heading">{title}<p class="data-deck">Οδηγοί, ομάδες και οι λεπτομέρειες<br>που κρίνουν τον αγώνα.</p></header>{source}{lead}{reportnav()}<div class="data-layout">{reports()}{explanation}</div>'
    if c=='b':return f'<header class="data-heading"><div>{title}</div>{lead}</header>{source}{reportnav()}<div class="data-layout">{reports()}{explanation}</div>'
    return f'<div class="notebook-topline"><span>F1Stories / Αναφορά πρωταθλήματος</span><a href="index.html">Το σημειωματάριο ↗</a></div><header class="data-heading"><div>{title}</div><dl><dt>Σεζόν</dt><dd>2026</dd><dt>Γύρος</dt><dd>11</dd><dt>Έκδοση δεδομένων</dt><dd>22.08.2026</dd></dl></header>{source}<div class="data-layout"><div>{reportnav()}{reports()}</div>{explanation}</div>'
def document(c,page,body):
    return f'<!doctype html><html lang="el"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="robots" content="noindex,nofollow"><title>{NAMES[c]} · { {"home":"F1Stories","article":A[0]["title"],"data":"F1 Data Hub"}[page]}</title><link rel="icon" href="/source/images/favicon.png"><link rel="stylesheet" href="style.css"><script src="/interactions.js" defer></script></head><body class="page-{page}"><a class="skip-link" href="#main">Μετάβαση στο περιεχόμενο</a>{header(c,page)}<div class="page-shell"><main id="main">{body}</main>{foot(c)}</div></body></html>'
for c in 'abc':
    directory=ROOT/f'concept-{c}'; directory.mkdir(exist_ok=True)
    for page,file,body in [('home','index.html',globals()['home_'+c]()),('article','article.html',article(c)),('data','data.html',data(c))]:
        (directory/file).write_text(document(c,page,body))
print('Rendered 9 isolated pages from content.json')
